/* MicroCS Studio - LVGL IntelliSense (docs/LVGL.md). The API table (lvgl_api.js, ~350 KB, generated by
 * tools/lvgl_gen/studio_data.py from lvgl_api.json) is loaded the first time a script mentions lv_* / LV_* or
 * the user types "lv" - never for other scripts. Completion, parameter info and hover use it for the
 * functions, constants, symbols, fonts and struct types that C# scripts call with the C names. */
window.StudioLvgl = (function () {
  let state = 0;                           /* 0 not loaded, 1 loading, 2 ready */
  const waiting = [], memo = Object.create(null);
  const MENTION = /\b(?:lv_|LV_|lvgl_host_)\w/;
  function data() { return state === 2 ? window.MCS_LVGL : null; }
  function load(cb) {
    if (state === 2) { if (cb) cb(); return; }
    if (cb) waiting.push(cb);
    if (state === 1 || typeof document === "undefined") return;
    state = 1;
    const s = document.createElement("script");
    s.src = "lvgl_api.js";
    s.onload = () => { state = window.MCS_LVGL ? 2 : 0; for (const f of waiting.splice(0)) f(); };
    s.onerror = () => { state = 0; waiting.length = 0; };
    document.head.appendChild(s);
  }
  /* members in the shape docs.js / lang.js use: {name, kind, params:[{type,name,def}], ret, doc, cls, inst} */
  function fn(name) {
    const d = data();
    if (!d || !Object.prototype.hasOwnProperty.call(d.f, name)) return null;
    return memo[name] || (memo[name] = [{ name, kind: "m", ret: d.f[name][0], params: d.f[name][1].map(([type, n]) => ({ type, name: n, def: null })), doc: d.f[name][2], cls: "", inst: false }]);
  }
  /* completion items whose name starts with / contains the prefix (case-insensitive), at most `max` */
  function items(prefix, opts) {
    const d = data(); if (!d) return [];
    const lp = (prefix || "").toLowerCase(), out = [];
    if (lp.length < 2) return out;
    const hit = (n) => n.toLowerCase().startsWith(lp) || (lp.length > 3 && n.toLowerCase().includes(lp));
    if (opts && opts.afterNew) {
      for (const c of d.classes) if (hit(c)) out.push({ label: c, kind: "c", detail: "LVGL struct", cls: c });
      return out.slice(0, 60);
    }
    for (const n in d.f) if (hit(n)) out.push({ label: n, kind: "m", detail: d.f[n][0], mems: fn(n), owner: "" });
    for (const n of d.k) if (hit(n)) out.push({ label: n, kind: "f", detail: "int const" });
    for (const n of d.s) if (hit(n)) out.push({ label: n, kind: "f", detail: "string const" });
    for (const n in d.v) if (hit(n)) out.push({ label: n, kind: "f", detail: d.v[n] });
    return out.sort((a, b) => (a.label.toLowerCase().startsWith(lp) ? 0 : 1) - (b.label.toLowerCase().startsWith(lp) ? 0 : 1) || a.label.length - b.label.length || a.label.localeCompare(b.label)).slice(0, 80);
  }
  function kindOf(name) {
    const d = data(); if (!d) return null;
    if (d.k.includes(name)) return "int constant";
    if (d.s.includes(name)) return "string constant";
    if (d.v[name]) return d.v[name] + " (font / object)";
    return null;
  }
  return { load, fn, items, kindOf, mentions: (src) => MENTION.test(src || ""), ready: () => state === 2 };
})();
